1|// Single swap point for the music-mode control (style stickers plus the
2|// Chopin button). The player renders <MusicStyleControl /> and must not
3|// know its internals: replacing this file and
4|// app/styles/music-style-control.css swaps the whole design.
5|"use client";
6|
7|import { useEffect, useRef, useState } from "react";
8|import type { MusicMode, MusicModeId } from "@/core/music";
9|import { heroArt, type HeroArt } from "../skin-art";
10|import { useSkin } from "../use-skin";
11|import { ButtonFx } from "../button-fx";
12|
13|export type MusicStyleControlProps = {
14|  modes: MusicMode[];
15|  current: MusicModeId | null;
16|  onAdvance: (to?: MusicModeId) => void;
17|};
18|
19|// One pop cycle: how long the newly current button replays its animation.
20|const ANIM_MS = 600;
21|
22|function stickerFor(id: string, label: string, art: HeroArt): string {
23|  const piano = /piano/i.test(id) || /piano/i.test(label);
24|  return piano ? art.piano : art.orchestra;
25|}
26|
27|export function MusicStyleControl({ modes, current, onAdvance }: MusicStyleControlProps) {
28|  const styles = modes.filter((m) => m.kind === "style");
29|  const playlist = modes.find((m) => m.kind === "playlist") ?? null;
30|  const art = heroArt(useSkin());
31|  // The button whose mode just became current pops once, then rests still.
32|  const [anim, setAnim] = useState<MusicModeId | null>(null);
33|  const firstRef = useRef(true);
34|  const animTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
35|
36|  // Session-driven changes (Chopin toggle-back) animate too; the first
37|  // render is skipped so restoring prefs on load stays still.
38|  useEffect(() => {
39|    if (firstRef.current) {
40|      firstRef.current = false;
41|      return;
42|    }
43|    setAnim(current);
44|    if (animTimer.current) clearTimeout(animTimer.current);
45|    animTimer.current = setTimeout(() => setAnim(null), ANIM_MS);
46|    return () => {
47|      if (animTimer.current) clearTimeout(animTimer.current);
48|    };
49|  }, [current]);
50|
51|  useEffect(
