1|// The read-aloud control: play/pause plus a narration-only volume
2|// slider. Light mode is the default; colours come from tokens.
3|"use client";
4|
5|import { useEffect, useRef, useState } from "react";
6|import { heroArt } from "../skin-art";
7|import { useSkin } from "../use-skin";
8|import { ButtonFx } from "../button-fx";
9|import { useNarration } from "./context";
10|
11|// One face-in cycle: how long the button replays its change animation
12|// after a toggle, matching the longest per-skin face-in.
13|const ANIM_MS = 600;
14|
15|export function ReadAloud() {
16|  const { on, status, playing, volume, toggle, setVolume } = useNarration();
17|  const busy = on && status !== "ready" && status !== "error";
18|  const label = !on ? "Read aloud" : playing ? "Pause" : "Read aloud";
19|  const art = heroArt(useSkin());
20|  // The toggle flips state, so it replays the one-shot face-in once.
21|  const [anim, setAnim] = useState(false);
22|  const animTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
23|
24|  useEffect(
25|    () => () => {
26|      if (animTimer.current) clearTimeout(animTimer.current);
27|    },
28|    [],
29|  );
30|
31|  function onToggle() {
32|    toggle();
33|    setAnim(true);
34|    if (animTimer.current) clearTimeout(animTimer.current);
35|    animTimer.current = setTimeout(() => setAnim(false), ANIM_MS);
36|  }
37|
38|  return (
39|    <div className="read-aloud" data-state={status} data-on={on} data-art="hero">
40|      <button
41|        type="button"
42|        className="read-aloud-btn"
43|        data-anim={anim ? "1" : undefined}
44|        onClick={onToggle}
45|        aria-pressed={on && playing}
46|        aria-label={label}
47|        title={label}
48|      >
49|        <span className="read-aloud-frame">
50|          <img className="read-aloud-art" src={art.narrate} alt="" width={40} height={40} />
51|          <ButtonFx kind="narrate" />
52|        </span>
53|        <span className="read-aloud-label">{label}</span>
54|      </button>
55|      <label className="read-aloud-volume">
56|        <span className="sr-only">Narration volume</span>
57|        <input
58|          type="range"
59|          min={0}
60|          max={1}
61|          step={0.05}
62|          value={volume}
63|          onChange={(e) => setVolume(Number(e.target.value))}
64|          aria-label="Narration volume"
65|        />
66|      </label>
67|      {on && status === "loading" ? <p className="read-aloud-note">Getting the voice ready…</p> : null}
68|      {on && status === "error" ? (
69|        <p className="read-aloud-note" role="alert">
70|          The voice isn&apos;t available right now.
71|        </p>
72|      ) : null}
73|      {busy ? <span className="sr-only" aria-live="polite">Getting the voice ready…</span> : null}
74|    </div>
75|  );
76|}

