82|export function PictureButton({
83|  skin,
84|  label,
85|  onClick,
86|}: {
87|  skin: PictureSkin;
88|  label: string;
89|  onClick: (e: React.MouseEvent<HTMLButtonElement>) => void;
90|}) {
91|  // The click replays the one-shot press (classic skins) or POW (comic)
92|  // once, then rests still.
93|  const [press, setPress] = useState(false);
94|  const pressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
95|
96|  useEffect(
97|    () => () => {
98|      if (pressTimer.current) clearTimeout(pressTimer.current);
99|    },
100|    [],
101|  );
102|
103|  function handleClick(e: React.MouseEvent<HTMLButtonElement>) {
104|    pressButton(e);
105|    setPress(true);
106|    if (pressTimer.current) clearTimeout(pressTimer.current);
107|    pressTimer.current = setTimeout(() => setPress(false), 400);
108|    onClick(e);
109|  }
110|
111|  return (
112|    <button
113|      type="button"
114|      className={`pic-btn pic-btn-${skin}`}
115|      data-picture-skin={skin}
116|      data-press={press ? "1" : undefined}
117|      onClick={handleClick}
118|    >
119|      <span className="pic-btn-art" aria-hidden="true">
120|        <ButtonArt skin={skin} />
121|        <ButtonFx kind="picture" />
122|      </span>
123|      <span className="pic-btn-lbl">{label}</span>
124|    </button>
125|  );
